mapper.select:
select t.PRODUCT, t.CAL_NAME, t.CAL_DESCRIPTION, t.INCLUDE_VALUE, t.EXCLUSION_VALUE from ww_calendar t where 1=1
and t.PRODUCT = #{product}
and instr(t.CAL_NAME, #{lCalName}) > 0
and t.CAL_NAME = #{calName}
and exists ( select tsupr.product_id From ww_sys_user tsu,ww_product tp,ww_sys_user_product_ref tsupr where tsu.login_name=tsupr.user_id and tp.p_id=tsupr.product_id and tp.p_id=t.product and tsu.login_name=#{loginName} )

mapper.delete:
    delete from ww_calendar
	where product = #{product}
	and cal_name = #{calName}

mapper.update:
    update ww_calendar 
    set
		CAL_DESCRIPTION = #{calDescription,jdbcType=VARCHAR},
	    INCLUDE_VALUE = #{includeValue,jdbcType=VARCHAR},
	    EXCLUSION_VALUE = #{exclusionValue,jdbcType=VARCHAR}
    where product = #{product}
    	and cal_name = #{calName}

    update ww_calendar 
    set product = #{product}

		,CAL_DESCRIPTION = #{calDescription}


	   ,INCLUDE_VALUE = #{includeValue}


	   ,EXCLUSION_VALUE = #{exclusionValue}

    where product = #{product}
    and cal_name = #{calName}
